/* ===== 纯函数区（首个无属性 script）：可被 Node _test.js 提取并断言 ===== */
  function escapeHTML(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function escapeAttr(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
  function slugify(s){ return String(s==null?'':s).toLowerCase().trim().replace(/[^\w\u4e00-\u9fa5]+/g,'-').replace(/^-+|-+$/g,'')||'resume'; }
  function defaultData(){
    return { name:'', title:'', summary:'', contacts:[], experience:[], education:[], skills:[], projects:[], links:[] };
  }
  function completeness(d){
    var total=8, got=0;
    function chk(c){ if(c) got++; }
    chk(d.name && d.name.trim());
    chk(d.title && d.title.trim());
    chk(d.summary && d.summary.trim());
    chk(d.contacts && d.contacts.length>0);
    chk(d.experience && d.experience.length>0);
    chk(d.education && d.education.length>0);
    chk(d.skills && d.skills.length>0);
    chk(d.projects && d.projects.length>0);
    return Math.round(got/total*100);
  }
  function renderCV(d){
    var h='';
    h += '<header class="cv-head">';
    h += '<h1>'+escapeHTML(d.name||'你的名字')+'</h1>';
    if(d.title) h += '<div class="cv-title">'+escapeHTML(d.title)+'</div>';
    if(d.contacts && d.contacts.length){ h += '<div class="cv-contacts">'+ d.contacts.map(function(c){ return '<span>'+escapeHTML(c.label||'')+(c.value?'：'+escapeHTML(c.value):'')+'</span>'; }).join('')+'</div>'; }
    h += '</header>';
    if(d.summary) h += '<section><h2>简介</h2><p>'+escapeHTML(d.summary)+'</p></section>';
    if(d.experience && d.experience.length){ h += '<section><h2>工作经历</h2>'; d.experience.forEach(function(e){ h += '<div class="cv-item"><div class="cv-item-h"><span class="cv-role">'+escapeHTML(e.role||'')+'</span>'+(e.org?'<span class="cv-org">'+escapeHTML(e.org)+'</span>':'')+'<span class="cv-date">'+[e.start,e.end].filter(Boolean).join(' – ')+'</span></div>'; if(e.points&&e.points.length){ h += '<ul>'+e.points.map(function(p){return '<li>'+escapeHTML(p)+'</li>';}).join('')+'</ul>'; } h += '</div>'; }); h += '</section>'; }
    if(d.education && d.education.length){ h += '<section><h2>教育背景</h2>'; d.education.forEach(function(e){ h += '<div class="cv-item"><div class="cv-item-h"><span class="cv-role">'+escapeHTML(e.school||'')+'</span>'+(e.degree?'<span class="cv-org">'+escapeHTML(e.degree)+'</span>':'')+'<span class="cv-date">'+[e.start,e.end].filter(Boolean).join(' – ')+'</span></div></div>'; }); h += '</section>'; }
    if(d.skills && d.skills.length){ h += '<section><h2>技能</h2><div class="cv-skills">'+ d.skills.map(function(s){return '<span class="cv-skill">'+escapeHTML(s)+'</span>';}).join('')+'</div></section>'; }
    if(d.projects && d.projects.length){ h += '<section><h2>项目</h2>'; d.projects.forEach(function(p){ h += '<div class="cv-item"><div class="cv-item-h"><span class="cv-role">'+escapeHTML(p.name||'')+'</span>'+(p.link?'<a class="cv-link" href="'+escapeAttr(p.link)+'">'+escapeHTML(p.link)+'</a>':'')+'</div>'+(p.desc?'<p>'+escapeHTML(p.desc)+'</p>':''); }); h += '</section>'; }
    if(d.links && d.links.length){ h += '<section><h2>链接</h2><ul>'+ d.links.map(function(l){ return '<li><a href="'+escapeAttr(l.url||'#')+'">'+escapeHTML(l.label||l.url)+'</a></li>'; }).join('')+'</ul></section>'; }
    return h;
  }
  function toJSON(d){ return JSON.stringify(d, null, 2); }
  function fromJSON(str){ var o = JSON.parse(str); if(!o || typeof o!=='object') throw new Error('bad'); var d = defaultData();
    ['name','title','summary'].forEach(function(k){ if(typeof o[k]==='string') d[k]=o[k]; });
    ['contacts','experience','education','skills','projects','links'].forEach(function(k){ if(Array.isArray(o[k])) d[k]=o[k]; });
    return d;
  }
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      escapeHTML:escapeHTML, escapeAttr:escapeAttr, slugify:slugify,
      defaultData:defaultData, completeness:completeness, renderCV:renderCV,
      toJSON:toJSON, fromJSON:fromJSON
    };
  }
  if (typeof window !== 'undefined') {
    window.CVForgePure = {
      escapeHTML:escapeHTML, escapeAttr:escapeAttr, slugify:slugify,
      defaultData:defaultData, completeness:completeness, renderCV:renderCV,
      toJSON:toJSON, fromJSON:fromJSON
    };
  }
